using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class BuildDetailedPriest {
 [Serializable] public class Joint{public string name;public float[] head,tail;}
 [Serializable] public class Part{public string name;public float[] vertices,normals,uv,weights;public int[] indices;}
 [Serializable] public class Data{public Joint[] bones;public Part[] parts;}
 static Vector3 V(float[] f,int i=0)=>new Vector3(f[i],f[i+1],f[i+2]);
 static Transform End(Animator a,HumanBodyBones id){string n=id.ToString();string end=n switch{"Hips"=>"Spine","Spine"=>"Chest","Chest"=>"Neck","Neck"=>"Head",_=>null};if(n.Contains("UpperArm"))end=n.Replace("UpperArm","LowerArm");if(n.Contains("LowerArm"))end=n.Replace("LowerArm","Hand");if(n.Contains("Shoulder"))end=n.Replace("Shoulder","UpperArm");if(n.Contains("UpperLeg"))end=n.Replace("UpperLeg","LowerLeg");if(n.Contains("LowerLeg"))end=n.Replace("LowerLeg","Foot");if(n.Contains("Foot"))end=n.Replace("Foot","Toes");if(n.Contains("Proximal"))end=n.Replace("Proximal","Intermediate");if(n.Contains("Intermediate"))end=n.Replace("Intermediate","Distal");return end!=null?a.GetBoneTransform((HumanBodyBones)Enum.Parse(typeof(HumanBodyBones),end)):null;}
 public static string Run(){return Build("Priest","Mage");} public static string Scouts(){return Build("Defender","Archer")+Build("Defender","Shinobi")+Build("Defender","Berserker");}
 public static string Build(string source,string role){string dir="Assets/03_Models/Characters/CindersDetailed/"+source;AssetDatabase.Refresh();var data=Newtonsoft.Json.JsonConvert.DeserializeObject<Data>(System.IO.File.ReadAllText(dir+"/"+source+"Geometry.json"));var go=UnityEngine.Object.Instantiate(Resources.Load<GameObject>("Presentation/Human/HumanPlayer"));go.name=role+" - Peregrino velado";var a=go.GetComponentInChildren<Animator>();a.enabled=false;foreach(var r in go.GetComponentsInChildren<Renderer>())UnityEngine.Object.DestroyImmediate(r.gameObject);var ids=data.bones.Select(b=>(HumanBodyBones)Enum.Parse(typeof(HumanBodyBones),b.name)).ToArray();var bones=ids.Select(b=>a.GetBoneTransform(b)??a.GetBoneTransform(HumanBodyBones.Hips)).ToArray();var matrices=new Matrix4x4[bones.Length];var rotations=new Quaternion[bones.Length];
 for(int j=0;j<bones.Length;j++){var dirSource=V(data.bones[j].tail)-V(data.bones[j].head);var child=End(a,ids[j]);Vector3 dirTarget=child?child.position-bones[j].position:ids[j].ToString().Contains("Hand")||ids[j].ToString().Contains("Distal")?(ids[j].ToString().StartsWith("Left")?Vector3.left:Vector3.right)*dirSource.magnitude:Vector3.up*dirSource.magnitude;rotations[j]=Quaternion.FromToRotation(dirSource,dirTarget);var from=Quaternion.FromToRotation(Vector3.up,dirSource);var to=Quaternion.FromToRotation(Vector3.up,dirTarget);float stretch=child?Mathf.Clamp(dirTarget.magnitude/dirSource.magnitude,.5f,1.8f):1;matrices[j]=Matrix4x4.TRS(bones[j].position,rotations[j],Vector3.one)*Matrix4x4.Translate(-V(data.bones[j].head));}
 foreach(var p in data.parts){int n=p.vertices.Length/3;var vs=new Vector3[n];var ns=new Vector3[n];var uv=new Vector2[n];var weights=new BoneWeight[n];for(int i=0;i<n;i++){var point=V(p.vertices,i*3);var normal=V(p.normals,i*3);for(int k=0;k<4;k++){int bone=p.indices[i*4+k];float w=p.weights[i*4+k];vs[i]+=matrices[bone].MultiplyPoint3x4(point)*w;ns[i]+=rotations[bone]*normal*w;}ns[i].Normalize();uv[i]=new Vector2(p.uv[i*2],p.uv[i*2+1]);weights[i]=new BoneWeight{boneIndex0=p.indices[i*4],boneIndex1=p.indices[i*4+1],boneIndex2=p.indices[i*4+2],boneIndex3=p.indices[i*4+3],weight0=p.weights[i*4],weight1=p.weights[i*4+1],weight2=p.weights[i*4+2],weight3=p.weights[i*4+3]};}
 var mesh=new Mesh{name=p.name};mesh.vertices=vs;mesh.normals=ns;mesh.uv=uv;mesh.triangles=Enumerable.Range(0,n).ToArray();mesh.boneWeights=weights;mesh.bindposes=bones.Select(b=>b.worldToLocalMatrix*go.transform.localToWorldMatrix).ToArray();mesh.RecalculateBounds();mesh.RecalculateTangents();string path=dir+"/"+role+"_"+p.name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.vertices=vs;old.normals=ns;old.uv=uv;old.triangles=mesh.triangles;old.boneWeights=weights;old.bindposes=mesh.bindposes;old.RecalculateBounds();old.RecalculateTangents();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,path);
 string part=p.name.Split('_')[0];string color=part switch{"helmet"=>"helmet-text.png","robe"=>"robe text.png","mantle"=>"mantle text.png","stripes"=>"stripes.png",_=>"body text.png"};string normalTex=part+" normal.png";var mp=dir+"/"+role+"_"+p.name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,mp);}mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(dir+"/"+color));mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Smoothness",.24f);mat.SetFloat("_Metallic",part=="helmet"?.45f:0);mat.SetFloat("_Cull",0);var ti=AssetImporter.GetAtPath(dir+"/"+normalTex) as TextureImporter;if(ti){if(ti.textureType!=TextureImporterType.NormalMap){ti.textureType=TextureImporterType.NormalMap;ti.SaveAndReimport();}mat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(dir+"/"+normalTex));mat.EnableKeyword("_NORMALMAP");mat.SetFloat("_BumpScale",.65f);}EditorUtility.SetDirty(mat);var obj=new GameObject(p.name);obj.transform.SetParent(go.transform,false);var r=obj.AddComponent<SkinnedMeshRenderer>();r.sharedMesh=mesh;r.sharedMaterial=mat;r.bones=bones;r.rootBone=a.GetBoneTransform(HumanBodyBones.Hips);r.localBounds=mesh.bounds;r.updateWhenOffscreen=true;}
 if(role=="Berserker")a.runtimeAnimatorController=Resources.Load<RuntimeAnimatorController>("Presentation/Human/Berserker");a.enabled=true;PrefabUtility.SaveAsPrefabAsset(go,"Assets/Resources/Presentation/Classes/"+role+".prefab");UnityEngine.Object.DestroyImmediate(go);AssetDatabase.SaveAssets();return role+": native skin weights transferred to animation-compatible humanoid";}
}



